-- What's new for the 2026-11-12 release, published when the migration runs
-- (the deploy), so everyone sees them once at their next visit. Staff can edit
-- or unpublish them on Help, Feedback & notes (#/help-admin).
INSERT INTO release_notes (title, body, page, tour_key, capability, published_at, created_by)
SELECT * FROM (
  SELECT 'You stay signed in' AS title, 'No more being signed out every few hours. With "Keep me signed in" ticked, you stay signed in while you use the app, and for up to 14 days without opening it (everyone signs in again at least every 90 days). Leave it unticked on a shared computer: you''re signed out when the browser closes.' AS body, NULL AS page, NULL AS tour_key, NULL AS capability, NOW() - INTERVAL 0 SECOND AS published_at, 'release-1112' AS created_by
  UNION ALL SELECT 'Pipeline syncs with the B151 again', 'The Pipeline is kept in step with the B151 every night, and Refresh from B151 is back on the page. Each quote''s Workbook link opens its Quoting Metrics sheet: the B151 row''s link, or, when that''s empty, the workbook in Drive named after the quote number.', '#/pipeline', '#/pipeline', 'page.estimate', NOW() - INTERVAL 1 SECOND, 'release-1112'
  UNION ALL SELECT 'Cash Flow runs on app data', 'The cash forecast no longer reads the B250. Today''s cash is the QuickBooks bank accounts ticked on the page (or the opening you type), and every line comes from QuickBooks, the project schedules and what you enter in the app. The Compare with the B250 section is gone.', '#/cashflow', '#/cashflow', 'page.cashflow', NOW() - INTERVAL 2 SECOND, 'release-1112'
  UNION ALL SELECT 'Assignments follow the Job Schedule more closely', 'The nightly Job Schedule import now starts a new set of dates at each yellow first-day cell and updates the app line that matches each phase''s dates, so jobs with more than one visit (like IDL 6016) no longer get merged into one line.', '#/assignment', '#/assignment', 'page.assignment', NOW() - INTERVAL 3 SECOND, 'release-1112'
  UNION ALL SELECT 'Job Schedule phases and overage days in Data Review', 'Data Review, Schedule tab: every phase on the Job Schedule is checked against the app, with its start, quoted end (the green cell) and overage days (orange days worked past it, counted in calendar days, weekends included). Differences and unclear colouring are listed for you to review. Finished phases are never changed by themselves.', '#/review', '#/review', 'page.customers', NOW() - INTERVAL 4 SECOND, 'release-1112'
  UNION ALL SELECT 'Drive sheets: read for reference, never applied', 'Crew Payment Schedule sheets, PO PDFs and completion forms are still read every night so their information is there for you, but they no longer change crew pay, amounts or dates in the app. Where a crew Payment Schedule sheet says something different from the app, Data Review, Crew payments lists it to decide.', '#/review', NULL, 'page.customers', NOW() - INTERVAL 5 SECOND, 'release-1112'
) d
WHERE NOT EXISTS (SELECT 1 FROM release_notes WHERE created_by = 'release-1112');
